import os
import re
import numpy as np
import matplotlib.pyplot as plt
from sklearn.decomposition import PCA
from openai import OpenAI
import glob
import json

# =============================================================================
# Configuration & Setup
# =============================================================================
# This script is designed to run within the CyberLoop repository.
# It expects logs to be in 'local/benchmarks/' generated by 'src/examples/wikipedia/demo.ts'.

# Directory containing the structured logs (JSONL format)
# Go up 3 levels: experiments/wikipedia/visualization.py -> experiments/wikipedia -> experiments -> root
LOG_DIR = os.path.join(os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__)))), 'local', 'benchmarks')

# Output directory for figures
OUTPUT_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'figures')

if not os.path.exists(OUTPUT_DIR):
    os.makedirs(OUTPUT_DIR)

API_KEY_NAME="PERSONAL_OPENAI_API_KEY"
# Initialize OpenAI Client (Make sure OPENAI_API_KEY is set in environment)
client = OpenAI(api_key=os.environ.get(API_KEY_NAME))

# =============================================================================
# Data Parsing
# =============================================================================

def load_logs(log_dir, scenario_filter=None):
    """
    Parses structured log files from the benchmark directory.
    Returns a list of runs, where each run contains metadata, trajectory, and kinematic data.
    """
    data = []

    # Files are named: run_{scenario}_{policy}_{timestamp}.log
    files = glob.glob(os.path.join(log_dir, 'run_*.log'))
    print(f"📂 Found {len(files)} log files in {log_dir}")

    for f in files:
        filename = os.path.basename(f)
        match = re.match(r'run_([^_]+)_([^_]+)_(.+)\.log', filename)
        if not match:
            continue

        scenario, policy, timestamp = match.groups()

        # Filter by scenario if requested
        if scenario_filter and scenario != scenario_filter:
            continue

        trajectory = []
        kinematics_series = []

        with open(f, 'r') as file:
            for line in file:
                try:
                    entry = json.loads(line)

                    # 1. State Trajectory
                    state = entry.get('state')
                    if state and isinstance(state, dict):
                        current_title = state.get('currentTitle')

                        # Add node to trajectory if it's a new step (avoid duplicates)
                        if current_title:
                            if not trajectory or trajectory[-1] != current_title:
                                trajectory.append(current_title)

                    # 2. Kinematic Telemetry
                    # format: { kinematics: { angle_deg, velocity, error, correction, stable, step } }
                    k = entry.get('kinematics')
                    if k:
                        kinematics_series.append(k)

                except json.JSONDecodeError:
                    continue

        if trajectory:
            data.append({
                'scenario': scenario,
                'policy': policy,
                'timestamp': timestamp,
                'path': trajectory,
                'kinematics': kinematics_series,
                'label': f"{policy}"  # Simplified label
            })

    return data

# =============================================================================
# Embedding & Analysis
# =============================================================================

def get_embeddings(texts):
    """Batch get embeddings from OpenAI."""
    if not texts:
        return np.array([])

    valid_texts = [t for t in texts if t]
    if not valid_texts:
        return np.array([])

    # Use small batching if necessary, but here we assume list is reasonable size
    res = client.embeddings.create(input=valid_texts, model="text-embedding-3-small")
    return np.array([d.embedding for d in res.data])

def plot_kinematics(runs, title_suffix, output_filename):
    """
    Generates a multi-panel plot for Kinematic Telemetry:
    1. Angle (Coherence)
    2. PID Error (Rejection)
    3. Correction Magnitude (Control Signal)
    """
    # Filter runs that actually have kinematic data
    kinematic_runs = [r for r in runs if r['kinematics']]

    if not kinematic_runs:
        print(f"⚠️ No kinematic data found for {title_suffix}. Skipping kinematic plot.")
        return

    print(f"📈 Plotting Kinematics for {len(kinematic_runs)} runs...")

    fig, axes = plt.subplots(3, 1, figsize=(12, 12), sharex=True)

    # Define style map (Reuse consistent colors)
    style_map = {
        'baseline-a1': {'color': 'tab:red', 'ls': ':', 'marker': 'x', 'label': 'Baseline A1'},
        'baseline-a2': {'color': 'tab:ｌｌorange', 'ls': '--', 'marker': 'o', 'label': 'Baseline A2'},
        'baseline-a3': {'color': 'tab:purple', 'ls': '-.', 'marker': '^', 'label': 'Baseline A3'},
        'cyberloop-strict': {'color': 'tab:cyan', 'ls': '-', 'marker': 'D', 'label': 'CyberLoop (Strict)'},
        'cyberloop': {'color': 'tab:blue', 'ls': '-', 'marker': 's', 'label': 'CyberLoop (Full)'},
        'cot': {'color': 'tab:green', 'ls': '-.', 'marker': '*', 'label': 'Baseline B (LLM CoT)'}
    }

    for run in kinematic_runs:
        policy = run['policy']
        data = run['kinematics']

        # Sort by step just in case
        data.sort(key=lambda x: x['step'])

        steps = [d['step'] for d in data]
        angles = [d['angle_deg'] for d in data]
        errors = [d['error'] for d in data]
        corrections = [d['correction'] for d in data]

        style = style_map.get(policy, {'color': 'gray', 'ls': '--', 'marker': '.', 'label': policy})

        # Panel 1: Angle
        axes[0].plot(steps, angles, label=style['label'], color=style['color'], ls=style['ls'], alpha=0.8)

        # Panel 2: PID Error
        axes[1].plot(steps, errors, label=style['label'], color=style['color'], ls=style['ls'], alpha=0.8)

        # Panel 3: Correction
        axes[2].plot(steps, corrections, label=style['label'], color=style['color'], ls=style['ls'], alpha=0.8)

    # Formatting
    axes[0].set_ylabel("Turning Angle (deg)")
    axes[0].set_title(f"Kinematic Stability: {title_suffix}")
    axes[0].grid(True, alpha=0.2)
    axes[0].legend(loc='upper right')
    # Add threshold line for U-Turn
    axes[0].axhline(y=90, color='gray', linestyle=':', alpha=0.5, label='90° Orthogonal')

    axes[1].set_ylabel("PID Error (Vector Rejection)")
    axes[1].grid(True, alpha=0.2)

    axes[2].set_ylabel("Correction Magnitude (0-1)")
    axes[2].set_xlabel("Step Index")
    axes[2].grid(True, alpha=0.2)
    # Add threshold line
    axes[2].axhline(y=0.6, color='red', linestyle=':', alpha=0.3, label='Intervention Threshold')

    plt.tight_layout()
    output_path = os.path.join(OUTPUT_DIR, output_filename)
    plt.savefig(output_path, dpi=300)
    print(f"✅ Kinematic plot saved: {output_path}")
    plt.close()

def run_visualization(scenario_id, title_suffix, output_filename, custom_landmarks=None):
    print(f"\n--- Processing Scenario: {scenario_id} ---")

    # 1. Load Data
    runs = load_logs(LOG_DIR, scenario_filter=scenario_id)

    if not runs:
        print(f"❌ No logs found for scenario '{scenario_id}'. Skipping.")
        return

    # 2. Plot Kinematics (New!)
    plot_kinematics(runs, title_suffix, f"kinematics_{scenario_id}.png")

    # 3. Build Unified Embedding Space for Trajectory Plot
    all_nodes_flat = []
    for r in runs:
        all_nodes_flat.extend(r['path'])

    unique_nodes = list(dict.fromkeys(all_nodes_flat))  # Preserve order, remove dupes

    if not unique_nodes:
        print("No unique nodes found.")
        return

    print(f"🧠 Fetching embeddings for {len(unique_nodes)} unique nodes...")
    raw_embs = get_embeddings(unique_nodes)

    # Add slight noise to prevent singular matrix if nodes are too few or identical
    embs = raw_embs + np.random.normal(0, 0.01, raw_embs.shape)

    # 4. PCA Projection
    if len(unique_nodes) < 3:
        print("⚠️ Not enough nodes for PCA. Using random projection.")
        coords_all = np.random.rand(len(unique_nodes), 2)
    else:
        print("Computing PCA...")
        pca = PCA(n_components=2)
        coords_all = pca.fit_transform(embs)

    node_map = {node: coord for node, coord in zip(unique_nodes, coords_all)}

    # 5. Plotting Trajectories
    plt.figure(figsize=(12, 10))

    # Define style map for known policies
    # Update this map based on your actual policy names from demo.ts
    style_map = {
        'baseline-a1': {'color': 'tab:red', 'ls': ':', 'marker': 'x', 'label': 'Baseline A1 (Greedy)'},
        'baseline-a2': {'color': 'tab:orange', 'ls': '--', 'marker': 'o', 'label': 'Baseline A2 (Greedy+Mem)'},
        'baseline-a3': {'color': 'tab:purple', 'ls': '-.', 'marker': '^', 'label': 'Baseline A3 (Greedy+Mem+Reflex)'},
        'cyberloop-strict': {'color': 'tab:cyan', 'ls': '-', 'marker': 'D', 'label': 'CyberLoop (Strict/Safety)'},
        'cyberloop': {'color': 'tab:blue', 'ls': '-', 'marker': 's', 'label': 'CyberLoop (Full)'},
        'cot': {'color': 'tab:green', 'ls': '-.', 'marker': '*', 'label': 'Baseline B (LLM CoT)'}
    }

    for run in runs:
        policy = run['policy']
        path = run['path']

        # Get style or default
        style = style_map.get(policy, {'color': 'gray', 'ls': '--', 'marker': '.', 'label': policy})

        path_coords = np.array([node_map[n] for n in path if n in node_map])
        if path_coords.size == 0: continue

        # Add Jitter for visibility of overlapping paths
        jitter = np.random.normal(0, 0.04, path_coords.shape)
        path_coords_jittered = path_coords + jitter

        # Plot Line
        plt.plot(path_coords_jittered[:, 0], path_coords_jittered[:, 1],
                 color=style['color'], label=style['label'], linestyle=style['ls'], linewidth=2, alpha=0.6)

        # Plot Markers
        plt.scatter(path_coords_jittered[:, 0], path_coords_jittered[:, 1],
                    color=style['color'], s=50, marker=style['marker'], alpha=0.7)

        # Annotate Steps (First and Last few, or strided to avoid clutter)
        # Showing start and end is usually most important
        plt.text(path_coords_jittered[0, 0], path_coords_jittered[0, 1], "Start", fontsize=9, fontweight='bold', color='black')
        plt.text(path_coords_jittered[-1, 0], path_coords_jittered[-1, 1], f"End ({len(path)})", fontsize=9, fontweight='bold', color=style['color'])

    # Highlight Landmarks
    key_landmarks = custom_landmarks if custom_landmarks else []
    for name in key_landmarks:
        if name in node_map:
            coord = node_map[name]
            plt.annotate(name, (coord[0], coord[1]),
                         xytext=(0, -20), textcoords="offset points",
                         ha='center', fontsize=10, weight='bold',
                         bbox=dict(boxstyle='round,pad=0.3', fc='white', alpha=0.5))

    plt.title(f"Trajectory Analysis: {title_suffix}", fontsize=16)
    plt.xlabel("Semantic Dimension 1 (PCA)")
    plt.ylabel("Semantic Dimension 2 (PCA)")
    plt.legend(loc='best')
    plt.grid(True, alpha=0.2)

    output_path = os.path.join(OUTPUT_DIR, output_filename)
    plt.savefig(output_path, dpi=300, bbox_inches='tight')
    print(f"✅ Plot saved: {output_path}")
    plt.close()

# =============================================================================
# Main Execution
# =============================================================================

if __name__ == "__main__":
    if not os.environ.get(API_KEY_NAME):
        print(f"❌ Please set {API_KEY_NAME} env var (required for embeddings)")
    else:
        # Run Visualization for known scenarios
        run_visualization(
            "revolution",
            "Coffee -> French Revolution",
            "pca_revolution.png",
            custom_landmarks=['Coffee', 'Battle of Vienna', 'French Revolution']
        )

        run_visualization(
            "tech",
            "Jacquard Loom -> CPU",
            "pca_tech.png",
            custom_landmarks=['Jacquard machine', 'Computer programming', 'Central processing unit']
        )
